changeSet.sql:
ALTER TABLE journal DROP CONSTRAINT ck_journal_type, DROP CONSTRAINT ck_journal_status;
ALTER TABLE journal ADD CONSTRAINT ck_journal_type CHECK (type IN ('DEPOSIT', 'CONVERSION'));
ALTER TABLE journal ADD CONSTRAINT ck_journal_status CHECK (status IN ('POSTED', 'VOID') AND (status = 'POSTED' OR type = 'CONVERSION'));

